import{_ as t,I as a,g as i,j as n}from"./chunks/framework.Ha9mtr6N.js";const p=JSON.parse('{"title":"Licenses & Limitations","description":"OmniCraft ERP licensing tiers, the Free trial limit, data privacy, and license key activation.","frontmatter":{"title":"Licenses & Limitations","description":"OmniCraft ERP licensing tiers, the Free trial limit, data privacy, and license key activation.","order":14},"headers":[],"relativePath":"docs/licenses.md","filePath":"docs/licenses.md"}'),r={name:"docs/licenses.md"};function o(s,e,l,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation Under Development</p><p><strong>Dear Users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, with regular updates and expansions, the reference materials are also being updated gradually.</p><p>At this time, please treat the documentation as a guide—it is currently incomplete, may temporarily lack descriptions for certain features, or contain minor inaccuracies.</p></div><h1 id="🔐-licenses-limitations" tabindex="-1">🔐 Licenses &amp; Limitations <a class="header-anchor" href="#🔐-licenses-limitations" aria-label="Permalink to &quot;🔐 Licenses &amp; Limitations&quot;">​</a></h1><p>OmniCraft ERP is distributed under a <strong>Shareware model with a fair trial</strong>. You can download the software, configure it to your needs, and maintain complete management records absolutely free until your business reaches a stable turnover.</p><p>This page explains in detail how our licensing tiers work, why the Free version has these specific boundaries, and how the offline cryptographic security of the application is designed.</p><hr><h2 id="📊-three-licensing-tiers" tabindex="-1">📊 Three Licensing Tiers <a class="header-anchor" href="#📊-three-licensing-tiers" aria-label="Permalink to &quot;📊 Three Licensing Tiers&quot;">​</a></h2><p>The program offers a simple, transparent graduation of features that grows alongside your business.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Feature / Capability</th><th style="text-align:center;">🆓 Free ($0)</th><th style="text-align:center;">🥈 Standard</th><th style="text-align:center;">👑 PRO</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>All Workspace Tabs</strong> (Workshop, Materials, Calculator, Workbench, Showcase, Sales, Cash Flow, Capital, Analytics)</td><td style="text-align:center;">✅ Full access</td><td style="text-align:center;">✅ Full access</td><td style="text-align:center;">✅ Full access</td></tr><tr><td style="text-align:left;"><strong>Sales Processing Limit</strong></td><td style="text-align:center;">⚠️ Up to 20 sales</td><td style="text-align:center;">♾️ Unlimited</td><td style="text-align:center;">♾️ Unlimited</td></tr><tr><td style="text-align:left;"><strong>Auto-Backups &amp; Security (WAL, GFS)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td style="text-align:left;"><strong>Multi-Workspaces</strong> (Multiple DB files)</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td></tr><tr><td style="text-align:left;"><strong>Global &quot;My Capital&quot; Tab</strong> (Personal Finance)</td><td style="text-align:center;">❌</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅</td></tr><tr><td style="text-align:left;"><strong>Global Theme Modules</strong> (Add-ons)</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ (Add-on purchase)</td><td style="text-align:center;">✅ (Add-on purchase)</td></tr></tbody></table><hr><h2 id="🆓-how-the-free-limit-works-20-sales" tabindex="-1">🆓 How the Free Limit Works (20 Sales) <a class="header-anchor" href="#🆓-how-the-free-limit-works-20-sales" aria-label="Permalink to &quot;🆓 How the Free Limit Works (20 Sales)&quot;">​</a></h2><p>The free version of OmniCraft ERP has no feature restrictions—you have full access to all analytical, planning, and inventory tools. The only limitation lies at the <strong>very end of the pipeline</strong>: registering the receipt of payment from a client.</p><h3 id="what-happens-when-the-limit-is-reached" tabindex="-1">What happens when the limit is reached? <a class="header-anchor" href="#what-happens-when-the-limit-is-reached" aria-label="Permalink to &quot;What happens when the limit is reached?&quot;">​</a></h3><p>Once the sales counter (in the &quot;Sales&quot; tab) reaches <strong>20 transactions</strong>, the program automatically switches to a secure <strong>Read-Only</strong> mode.</p><ul><li>🚫 <strong>Blocked actions:</strong> The &quot;Process Sale&quot; button in the <em>Sales</em> tab and the &quot;Complete Production&quot; button in the <em>Production</em> tab become inactive. A red warning banner appears on the screen, requesting license activation.</li><li>✅ <strong>Access is preserved:</strong> You can freely view all analytics, send batches to the workbench, purchase raw materials, create new recipes, view charts, and perform backups.</li><li>🔄 <strong>No data is lost:</strong> All your records, recipes, and setup remain intact. You can purchase a key at any time, enter it in Settings, and the limit will be instantly lifted without any data loss.</li></ul><h3 id="🛡️-psychological-protection-against-bypassing" tabindex="-1">🛡️ Psychological Protection Against Bypassing <a class="header-anchor" href="#🛡️-psychological-protection-against-bypassing" aria-label="Permalink to &quot;🛡️ Psychological Protection Against Bypassing&quot;">​</a></h3><p>Unlike other software where users try to &quot;reset&quot; trials by deleting historical logs, doing so in OmniCraft ERP is <strong>economically pointless</strong>.</p><p>The entire value of the system is built on the continuity of historical data. If you manually delete old receipts or clear your sales history to bypass the limit, you will <strong>completely destroy</strong>:</p><ol><li>Your management balance sheet (Capital).</li><li>Your transaction history (Cash Flow/DDS).</li><li>Revenue charts and your Break-Even Point in Analytics.</li><li>The accuracy of FIFO cost calculation in your finished goods warehouse.</li></ol><p>Thus, you are personally interested in the integrity and continuity of your database. Purchasing a license is not just a &quot;software unlock,&quot; but an investment in preserving the digital foundation of your business.</p><hr><h2 id="🛠-technical-protection-architecture-offline-checks" tabindex="-1">🛠 Technical Protection Architecture (Offline Checks) <a class="header-anchor" href="#🛠-technical-protection-architecture-offline-checks" aria-label="Permalink to &quot;🛠 Technical Protection Architecture (Offline Checks)&quot;">​</a></h2><p>OmniCraft ERP is a local desktop application. Since we do not use cloud databases to store your financial records, the license check must be completely <strong>autonomous</strong> and work offline.</p><h3 id="_1-hardware-fingerprint-hwid" tabindex="-1">1. Hardware Fingerprint (HWID) <a class="header-anchor" href="#_1-hardware-fingerprint-hwid" aria-label="Permalink to &quot;1. Hardware Fingerprint (HWID)&quot;">​</a></h3><p>Upon first launch, the program generates a unique identifier for your computer (Hardware ID). It is built on a hashed UUID of the motherboard and local OS configuration parameters.</p><ul><li><strong>Privacy:</strong> The HWID is just an anonymous string of characters (e.g., <code>A1B2-C3D4-E5F6-G7H8</code>). It does not contain personal data, IP addresses, or file names.</li><li><strong>Purpose:</strong> The license key is strictly bound to this fingerprint. A single key can only be activated on the specific computer for which it was generated.</li></ul><h3 id="_2-asymmetric-encryption-rsa" tabindex="-1">2. Asymmetric Encryption (RSA) <a class="header-anchor" href="#_2-asymmetric-encryption-rsa" aria-label="Permalink to &quot;2. Asymmetric Encryption (RSA)&quot;">​</a></h3><p>To prevent cracking and key counterfeiting, we use asymmetric public-key cryptography:</p><ul><li>Only the <strong>RSA Public Key</strong> is compiled directly into the application&#39;s source code. It can only <em>verify</em> signatures, but cannot generate them.</li><li>The <strong>RSA Private Key</strong> is stored exclusively on our secure billing server (Cloudflare Workers) and never enters the application distribution.</li></ul><h3 id="_3-the-activation-process" tabindex="-1">3. The Activation Process <a class="header-anchor" href="#_3-the-activation-process" aria-label="Permalink to &quot;3. The Activation Process&quot;">​</a></h3><ol><li>You purchase a license on our website. Our billing server reads your HWID and generates a payload containing the license details (tier, Pro status, purchased add-on modules).</li><li>The server signs this payload using its Private Key and provides you with a Base64-encoded string (your License Key).</li><li>You paste this string into the &quot;License Key&quot; field within the <strong>Settings</strong> tab.</li><li>The application decodes the string, verifies the digital signature using its built-in Public Key, and compares the HWID. If everything matches, your full access is unlocked instantly.</li></ol><hr><h2 id="🕵️-anonymity-and-security-gdpr-ccpa-compliance" tabindex="-1">🕵️ Anonymity and Security (GDPR &amp; CCPA Compliance) <a class="header-anchor" href="#🕵️-anonymity-and-security-gdpr-ccpa-compliance" aria-label="Permalink to &quot;🕵️ Anonymity and Security (GDPR &amp; CCPA Compliance)&quot;">​</a></h2><p>We deeply respect our users&#39; privacy and strictly comply with international personal data protection standards (such as GDPR, CCPA, etc.). The OmniCraft ERP billing architecture is designed to <strong>never collect any of your personal data</strong>.</p><h3 id="the-anonymous-license-token-model" tabindex="-1">The Anonymous License Token Model <a class="header-anchor" href="#the-anonymous-license-token-model" aria-label="Permalink to &quot;The Anonymous License Token Model&quot;">​</a></h3><ul><li>No registration with email, phone number, or government ID is required during purchase on our website.</li><li>The billing system generates a random anonymous token (e.g., <code>LIC-XXXX-XXXX</code>).</li><li>Our server only stores an anonymous record: <code>[Token] | [License Tier] | [Hashed HWID List]</code>.</li></ul><h3 id="🔄-self-service-transferring-a-license-to-a-new-pc" tabindex="-1">🔄 Self-Service: Transferring a License to a New PC <a class="header-anchor" href="#🔄-self-service-transferring-a-license-to-a-new-pc" aria-label="Permalink to &quot;🔄 Self-Service: Transferring a License to a New PC&quot;">​</a></h3><p>What if your computer crashes or you buy a new laptop? Since we do not store your email address, you don&#39;t need to write to &quot;support&quot; to reset your hardware key. Instead, a self-service system does the job:</p><ol><li>You visit the license management section on the OmniCraft ERP website.</li><li>Enter your anonymous token (<code>LIC-XXXX-XXXX</code>) received upon purchase.</li><li>The system shows the active hardware IDs currently bound to the key, allowing you to <strong>manually unbind</strong> any old or broken computer to free up a slot for your new HWID.</li></ol><hr><h2 id="⚙️-where-to-view-your-hwid-and-activate-your-key" tabindex="-1">⚙️ Where to View Your HWID and Activate Your Key <a class="header-anchor" href="#⚙️-where-to-view-your-hwid-and-activate-your-key" aria-label="Permalink to &quot;⚙️ Where to View Your HWID and Activate Your Key&quot;">​</a></h2><p>All license operations are carried out in the <strong>&quot;Settings&quot;</strong> tab under the <em>License Management</em> section.</p><ol><li><strong>Identifier (HWID):</strong> The program automatically calculates your hardware ID and displays it at the top of the card. Click the copy icon 📋 to easily submit it when making a purchase.</li><li><strong>License Status:</strong> This section displays your current operating mode (<em>Free Version</em>, <em>Standard</em>, or <em>PRO</em>).</li><li><strong>Activation:</strong> Paste your copied Base64 license key into the field and click the <strong>&quot;Activate&quot;</strong> button. The application will verify the signature and write the active status to your local database.</li></ol><div class="tip custom-block"><p class="custom-block-title">Dynamic Window Title</p><p>As soon as you activate your license, the OS window title will update dynamically. Instead of just <em>OmniCraft ERP</em>, you will see a status indicator: <em>OmniCraft ERP (License Pro)</em> or <em>OmniCraft ERP (License, Modules [2])</em> if you have purchased additional add-on modules.</p></div>',43)])])}const y=t(r,[["render",o]]);export{p as __pageData,y as default};
